Import ListNotations.
Open Scope Z_scope.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Local Ltac transport_chunks segs m a bs ::= transport_chunks_fast segs m a bs.
Local Ltac footprint_after_store segs m a bs ::= footprint_after_store_fast segs m a bs.
Local Ltac mem_after_store ::= mem_after_store_fast.

(* [comment removed for export] *)
Local Ltac bge_klw RT LOWF LOW LOR KL :=
  lazymatch goal with A : ART RT ?S ?m0, MUx : munch _ ?m0 ?m1 |- _ =>
    assert (KL : keeps_live (rt_live RT S) m0 m1)
      by (let bb := fresh "bb" in let kk := fresh "kk" in let Hin := fresh "Hin" in let aa := fresh "aa" in let Haa := fresh "Haa" in
          let L1 := fresh "L" in let L2 := fresh "L" in let L3 := fresh "L" in
          intros bb kk Hin aa Haa; apply MUx;
          destruct (LOWF S m0 bb kk (bv_unsigned aa) A ltac:(repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; left; reflexivity) Hin Haa) as (L1 & L2 & L3);
          repeat match goal with H : rt_sp0 _ _ = _ |- _ => rewrite H in L3 end;
          cbn [outside]; clear - L1 L2 L3 LOW LOR; repeat split; try exact I; lia) end.
(* [comment removed for export] *)
Local Ltac bge_klc RT LOWF AG KL :=
  lazymatch type of AG with agree_on (fun a => aclient (rt_live RT ?S0) ?frs ?sp a /\ outside ?W a) ?m0 ?m1 =>
    lazymatch goal with A : ART RT ?S m0 |- _ =>
      assert (KL : keeps_live (rt_live RT S) m0 m1)
        by (let b := fresh "b" in let k := fresh "k" in let x := fresh "x" in let Hin := fresh "Hin" in let Hx := fresh "Hx" in
            let L1 := fresh "L" in let L2 := fresh "L" in let L3 := fresh "L" in
            apply (keeps_live_of_agree (rt_live RT S0) frs sp W m0 m1 (rt_live RT S) AG);
            [ intros b Hin; repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H in * end; exact Hin
            | intros b k x Hin Hx;
              destruct (LOWF S m0 b k x A ltac:(repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; left; reflexivity) Hin Hx) as (L1 & L2 & L3);
              cbn [outside]; clear - L1; repeat split; try exact I; lia ]) end end.
(* [comment removed for export] *)
Local Ltac live_sub_tac ::=
  let e := fresh "e" in let He := fresh "He" in intros e He;
  try solve [destruct He];
  first [ match goal with S : forall x, In x ?l -> In x ?l' |- In _ ?l' => lazymatch type of He with In _ l => exact (S _ He) end end
        | repeat match goal with H : rt_live _ _ = _ |- _ => rewrite H in * end;
          repeat first [ exact He
                       | match goal with S : forall x, In x ?l -> In x ?l' |- In _ ?l' => lazymatch type of He with In _ l => exact (S _ He) end end
                       | apply in_or_app; right
                       | right
                       | apply live_remove_sub in He ] ].
(* [comment removed for export] *)
Local Ltac bge_uctx ra s0 ras m UCTX AGF RA4096 SPA usp A :=
  rewrite ?unsigned_lit by lia;
  lazymatch goal with FRx : rw_cells asegs ?mc A _ |- chain_ok ?mc _ _ _ =>
    let FRc := fresh "FRc" in let REC := fresh "REC" in
    pose proof FRx as FRc; split_before FRc (C8 s0) REC; clear FRc;
    replace (C8 s0) with (C8 (Z_to_bv 64 (bv_unsigned s0))) in REC by (rewrite Z_to_bv_bv_unsigned; reflexivity);
    replace (C8 ra) with (C8 (Z_to_bv 64 (bv_unsigned ra))) in REC by (rewrite Z_to_bv_bv_unsigned; reflexivity);
    apply (chain_ok_push mc _ usp (bv_unsigned ra) (bv_unsigned s0) ras);
    [ lia | clear - SPA; Z.div_mod_to_equations; lia | unfold USTACK_TOP; lia | exact RA4096 | apply bv_unsigned_in_range
    | exact REC
    | apply (chain_ok_keep ras m mc usp (bv_unsigned s0) UCTX); eapply agree_sub; [exact AGF|];
      let x := fresh "x" in let Hx := fresh "Hx" in intros x Hx; cbv beta; split; [left; exact Hx| cbn [outside]; exact I] ] end.
(* [comment removed for export] *)
Local Ltac bge_base H := repeat match goal with E : rt_live _ _ = _ |- _ => rewrite E in H end.
(* [comment removed for export] *)
Local Ltac bge_klc2 RT LOWF AG KL :=
  lazymatch type of AG with agree_on (fun a => aclient (rt_live RT ?S0) ?frs ?sp a /\ outside ?W a) ?m0 ?m1 =>
    lazymatch goal with A : ART RT S0 ?mm |- _ =>
      assert (KL : keeps_live (rt_live RT S0) m0 m1)
        by (let b := fresh "b" in let k := fresh "k" in let x := fresh "x" in let Hin := fresh "Hin" in let Hx := fresh "Hx" in
            let L1 := fresh "L" in let L2 := fresh "L" in let L3 := fresh "L" in
            apply (keeps_live_of_agree (rt_live RT S0) frs sp W m0 m1 (rt_live RT S0) AG);
            [ intros b Hin; exact Hin
            | intros b k x Hin Hx;
              destruct (LOWF S0 mm b k x A ltac:(repeat match goal with H : rt_frames _ _ = _ |- _ => rewrite H end; left; reflexivity) Hin Hx) as (L1 & L2 & L3);
              cbn [outside]; clear - L1; repeat split; try exact I; lia ]) end end.

(* [comment removed for export] *)
Local Ltac norm_regset ::=
  repeat match goal with
  | |- context [@bvmap_set 5 word ?r ?v ?R] =>
      lazymatch R with TNode _ _ _ => idtac | TEmpty => idtac end;
      let p := eval vm_compute in (bv_key r) in
      change (@bvmap_set 5 word r v R) with (tset p v R);
      cbv beta iota delta [tset mkR]
  end.
(* [comment removed for export] *)
Local Ltac fp_dec :=
  lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
    lazymatch c with context [reg_get] => fail "open FP condition" | _ => idtac end;
    let w := eval vm_compute in c in change c with w; cbv iota end.
(* [comment removed for export] *)
Local Ltac fs_walk :=
  repeat first [ reflexivity
               | progress (rewrite ?fs_reg_get_set; fs_eqb_simp)
               | match goal with H : fs_agree ?F1 ?F2 |- context [reg_get ?F2 ?r] => rewrite (fs_agree_get F1 F2 r H) by reflexivity end ].
Local Ltac fs_agree_chain :=
  let r := fresh "r" in let Hr := fresh "Hr" in
  intros r Hr; apply fs_callee_cases in Hr; cbn [map In] in Hr;
  repeat (destruct Hr as [<-|Hr]); [..| destruct Hr]; fs_walk.

(* [comment removed for export] *)
Ltac fp_guard := lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
  lazymatch c with context [reg_get] => fail "fp_guard: open condition" | _ => idtac end;
  let v := eval vm_compute in c in
  replace c with v by (vm_compute; reflexivity); cbv iota end.

Section PBIL16.
Variable RT : rt_sig.
Hypothesis AF : art_facts RT.
Hypothesis GP : rt_gaps RT.
Hypothesis FKC : rt_fk_contracts RT.
Hypothesis PBG : pixBilateralGray_cps RT.
Hypothesis PGRGB : pixGetRGBComponent_cps RT.
Hypothesis PCRGB : pixCreateRGBImage_cps RT.
Hypothesis PXD : pixDestroy_cpsF RT.
Hypothesis PXDN : pixDestroy_null_cpsF RT.
Hypothesis RERR : returnError_cpsF RT e_returnErrorPtr.
Hypothesis LSTD : lept_stderr_cpsF RT.
Hypothesis PCOPY : pixCopy_nn_cpsF RT.

Theorem pixBilateral_16 : pixBilateral_case RT 16.
Proof using AF GP FKC PBG PGRGB PCRGB PXD PXDN RERR LSTD PCOPY.
Ltac pb_fpread F FA0 FA1 :=
      fs_reads;
      repeat (lazymatch goal with |- evt _ _ (MS _ _ (if ?c then _ else _) _ _ _ _) =>
                lazymatch c with context [reg_get (bvmap_set ?k1 ?v1 ?F0) ?r] =>
                  let E1 := fresh "E1" in
                  first [ assert (E1 : reg_get (bvmap_set k1 v1 F0) r = v1) by (rewrite (fs_reg_get_set F0 k1 r v1); fs_eqb_simp; reflexivity)
                        | assert (E1 : reg_get (bvmap_set k1 v1 F0) r = reg_get F0 r) by (rewrite (fs_reg_get_set F0 k1 r v1); fs_eqb_simp; reflexivity) ];
                  rewrite E1; clear E1 end end);
      repeat match goal with
      | |- context [reg_get F ?r] =>
          first [ let E := fresh "FA0r" in assert (E : reg_get F r = fs32 F_5_0) by exact FA0; rewrite E; clear E
                | let E := fresh "FA1r" in assert (E : reg_get F r = fs32 F_10_0) by exact FA1; rewrite E; clear E ]
      end.
Ltac fa_rw F FA0 FA1 :=
      repeat match goal with
      | |- context [reg_get F ?r] =>
          first [ let E := fresh "FA0r" in assert (E : reg_get F r = fs32 F_5_0) by exact FA0; rewrite E; clear E
